#include <gtest/gtest.h>

#include <algorithm>
#include <cmath>
#include <vector>

#include "analyzer/plugins/beatgridevidence.h"
#include "track/beats.h"

namespace {

constexpr double kBpm = 135.93;
constexpr double kOrigin = 0.1;
constexpr int kDuration = 64;

void feedPercussivePulses(mixxx::BeatGridEvidence* evidence,
        int sampleRate,
        int chunkFrames,
        bool softBass) {
    const double period = 60 / kBpm;
    std::vector<CSAMPLE> pulse(static_cast<size_t>(sampleRate * 0.2));
    for (size_t frame = 0; frame < pulse.size(); ++frame) {
        const double time = frame / static_cast<double>(sampleRate);
        const double transient = std::exp(-100 * time) *
                (0.75 * std::cos(2 * M_PI * 1400 * time) +
                        0.25 * std::cos(2 * M_PI * 2500 * time));
        // The high-frequency attack starts at the beat. The soft kick body
        // swells later and peaks at 60 ms; its crest is not another beat.
        const double envelope = softBass
                ? std::exp(-0.5 * std::pow((time - 0.06) / 0.018, 2))
                : std::exp(-40 * time);
        pulse[frame] = static_cast<CSAMPLE>(0.5 *
                (transient + 0.55 * std::cos(2 * M_PI * 65 * time) * envelope));
    }

    std::vector<CSAMPLE> stereo(chunkFrames * 2);
    int beatIndex = 0;
    int beatFrame = -static_cast<int>(pulse.size());
    int nextBeatFrame = static_cast<int>(std::lround(kOrigin * sampleRate));
    for (int start = 0; start < sampleRate * kDuration; start += chunkFrames) {
        const int count = std::min(chunkFrames, sampleRate * kDuration - start);
        for (int frame = 0; frame < count; ++frame) {
            const int position = start + frame;
            if (position >= nextBeatFrame) {
                beatFrame = nextBeatFrame;
                nextBeatFrame = static_cast<int>(std::lround(
                        (kOrigin + ++beatIndex * period) * sampleRate));
            }
            const int elapsed = position - beatFrame;
            const CSAMPLE value = elapsed >= 0 &&
                            elapsed < static_cast<int>(pulse.size())
                    ? pulse[elapsed]
                    : 0;
            stereo[frame * 2] = stereo[frame * 2 + 1] = value;
        }
        ASSERT_TRUE(evidence->processSamples(stereo.data(), count * 2));
    }
    evidence->prepare();
}

mixxx::BeatsPointer makeGrid(int sampleRate, double origin) {
    return mixxx::Beats::fromConstTempo(mixxx::audio::SampleRate(sampleRate),
            mixxx::audio::FramePos(origin * sampleRate).toNearestFrameBoundary(),
            mixxx::Bpm(kBpm));
}

} // namespace

TEST(BeatPhaseAlignmentTest, SoftBassCrestCannotOverrideTheEarlierPercussiveAttack) {
    for (const int sampleRate : {8000, 44100, 48000}) {
        for (const int chunkFrames : {500, 4096}) {
            SCOPED_TRACE(::testing::Message()
                    << "sample rate " << sampleRate << ", chunk " << chunkFrames);
            mixxx::BeatGridEvidence evidence;
            evidence.initialize(mixxx::audio::SampleRate(sampleRate));
            feedPercussivePulses(&evidence, sampleRate, chunkFrames, true);
            const auto result = evidence.evaluate(makeGrid(sampleRate, kOrigin), false);
            ASSERT_TRUE(result.grid);
            EXPECT_TRUE(result.grid->hasConstantTempo());
            EXPECT_FALSE(result.phaseChanges);
            for (const int beat : {32, 96}) {
                const auto attack = mixxx::audio::FramePos(
                        (kOrigin + beat * 60 / kBpm) * sampleRate);
                EXPECT_NEAR(attack.value(),
                        result.grid->findClosestBeat(attack).value(),
                        0.015 * sampleRate);
            }
        }
    }
}

TEST(BeatPhaseAlignmentTest, AnActuallyEarlyGridStillMovesToTheCommonAttack) {
    for (const int sampleRate : {8000, 44100, 48000}) {
        for (const int chunkFrames : {500, 4096}) {
            SCOPED_TRACE(::testing::Message()
                    << "sample rate " << sampleRate << ", chunk " << chunkFrames);
            mixxx::BeatGridEvidence evidence;
            evidence.initialize(mixxx::audio::SampleRate(sampleRate));
            feedPercussivePulses(&evidence, sampleRate, chunkFrames, false);
            const auto original = makeGrid(sampleRate, kOrigin - 0.04);
            const auto result = evidence.evaluate(original, false);
            ASSERT_TRUE(result.grid);
            EXPECT_TRUE(result.grid->hasConstantTempo());
            EXPECT_FALSE(result.phaseChanges);
            for (const int beat : {32, 96}) {
                const auto attack = mixxx::audio::FramePos(
                        (kOrigin + beat * 60 / kBpm) * sampleRate);
                const auto before = original->findClosestBeat(attack);
                const auto after = result.grid->findClosestBeat(attack);
                EXPECT_GT((after - before), 0.025 * sampleRate);
                EXPECT_NEAR(attack.value(), after.value(), 0.015 * sampleRate);
            }
        }
    }
}
